def top_tools(log, k=3):
    if k <= 0:
        return []
    counts = {}
    for raw in log:
        if not isinstance(raw, str):
            continue
        name = " ".join(raw.strip().lower().split())
        if name:
            counts[name] = counts.get(name, 0) + 1
    return sorted(counts.items(), key=lambda pair: (-pair[1], pair[0]))[:k]

def validate_record(record):
    if not isinstance(record, dict):
        raise ValueError("Expected a record dictionary")
    record_id = record.get("id")
    duration = record.get("duration")
    success = record.get("success")
    if not isinstance(record_id, str) or not record_id.strip():
        raise ValueError("Expected a nonempty id")
    if type(duration) not in (int, float) or duration < 0:
        raise ValueError("Expected a nonnegative numeric duration")
    if not isinstance(success, bool):
        raise ValueError("Expected boolean success")
    return {"id": record_id.strip(), "duration": float(duration), "success": success}

def test_valid_records():
    assert validate_record({"id": " r1 ", "duration": 1, "success": True}) == {"id": "r1", "duration": 1.0, "success": True}
    assert validate_record({"id": "r2", "duration": 0, "success": False}) == {"id": "r2", "duration": 0.0, "success": False}

def test_invalid_records():
    for invalid in ({}, None, {"id": "r1", "duration": "slow", "success": True}):
        try:
            validate_record(invalid)
        except ValueError:
            pass
        else:
            raise AssertionError("Expected ValueError")

